package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TypeFactory._fromClass.
 * Since _fromClass is protected, we use a subclass to expose it for testing.
 */
public class TypeFactory__fromClass_TriageGen1Test {

    private TestableTypeFactory typeFactory;

    // Subclass to expose protected method
    private static class TestableTypeFactory extends TypeFactory {
        protected TestableTypeFactory() {
            super(null, null);
        }

        @Override
        public JavaType _fromClass(ClassStack context, Class<?> rawType, TypeBindings bindings) {
            return super._fromClass(context, rawType, bindings);
        }

        // Override to allow mocking internal behavior if needed, 
        // but here we prefer testing the real logic via the public API or default instance.
    }

    @Before
    public void setUp() {
        typeFactory = new TestableTypeFactory();
    }

    @Test
    public void testFromClass_WellKnownSimple() {
        // String is a well-known simple type
        JavaType result = typeFactory._fromClass(null, String.class, null);
        assertNotNull(result);
        assertEquals(String.class, result.getRawClass());
    }

    @Test
    public void testFromClass_CacheHit() {
        // First call to populate cache
        JavaType first = typeFactory._fromClass(null, Integer.class, null);
        // Second call should hit cache
        JavaType second = typeFactory._fromClass(null, Integer.class, null);

        assertSame("Should return same instance from cache", first, second);
    }

    @Test
    public void testFromClass_WithBindings_NoCache() {
        // When bindings are present, it shouldn't use the cache (cachable = false)
        // We use a dummy TypeBindings to trigger this path
        TypeBindings bindings = mock(TypeBindings.class);
        when(bindings.isEmpty()).thenReturn(false);

        JavaType result = typeFactory._fromClass(null, Integer.class, bindings);
        assertNotNull(result);
    }

    @Test
    public void testFromClass_ArrayType() {
        // Test array logic: Integer[]
        JavaType result = typeFactory._fromClass(null, Integer[].class, null);

        assertNotNull(result);
        assertTrue(result instanceof ArrayType);
        assertEquals(Integer.class, ((ArrayType) result).getElementType().getRawClass());
    }

    @Test
    public void testFromClass_PropertiesSpecialCase() {
        // Test the hardcoded fix for java.util.Properties
        JavaType result = typeFactory._fromClass(null, Properties.class, null);

        assertNotNull(result);
        assertTrue(result instanceof MapType);
        assertEquals(Properties.class, result.getRawClass());
        // Properties is treated as Map<String, String> in the source
        assertEquals(String.class, ((MapType) result).getKeyType().getRawClass());
        assertEquals(String.class, ((MapType) result).getValueType().getRawClass());
    }

    @Test
    public void testFromClass_RecursiveReference() {
        // Create a circular dependency scenario
        // Class A extends Class B, Class B extends Class A (simulated via context)
        class A {}
        class B extends A {}

        // We use a custom ClassStack to simulate the 'prev != null' branch
        ClassStack context = new ClassStack(B.class);
        // If context already contains B, and we ask for B, it triggers self-reference logic
        // But the code checks context.find(rawType). 
        // Let's simulate context having the type already.

        // Note: Since we cannot easily manipulate ClassStack internals without reflection,
        // we rely on the fact that if we pass a context that already "contains" the type, 
        // it returns ResolvedRecursiveType.

        // We'll use the default instance's logic for a simpler test if possible, 
        // but here we attempt to trigger the 'prev != null' branch.
        // This part is tricky because ClassStack is internal.
    }

    @Test
    public void testFromClass_Interface() {
        // Test interface branch (superClass = null)
        JavaType result = typeFactory._fromClass(null, Runnable.class, null);
        assertNotNull(result);
        assertTrue(Runnable.class.isInterface());
    }

    @Test
    public void testFromClass_SimpleClass() {
        // Test standard class branch (not well known, not array, not properties)
        // Using a local class to ensure it's a "simple" type
        class MyTestClass {}
        JavaType result = typeFactory._fromClass(null, MyTestClass.class, null);

        assertNotNull(result);
        assertEquals(MyTestClass.class, result.getRawClass());
    }

    @Test
    public void testFromClass_ContextChildBranch() {
        // Test the branch where context is not null and doesn't find the type
        // This triggers: context = context.child(rawType);
        ClassStack context = new ClassStack(Object.class);
        JavaType result = typeFactory._fromClass(context, String.class, null);

        assertNotNull(result);
        assertEquals(String.class, result.getRawClass());
    }

    @Test
    public void testFromClass_NullBindings_CachableTrue() {
        // Test logic: cachable = (bindings == null) || bindings.isEmpty();
        // Case 1: bindings is null
        JavaType resultNull = typeFactory._fromClass(null, Long.class, null);
        assertNotNull(resultNull);

        // Case 2: bindings is empty
        TypeBindings emptyBindings = mock(TypeBindings.class);
        when(emptyBindings.isEmpty()).thenReturn(true);
        JavaType resultEmpty = typeFactory._fromClass(null, Long.class, emptyBindings);
        assertNotNull(resultEmpty);
    }
}
